def clean(row):return {k:(None if isinstance(v,float) and not math.isfinite(v) else v) for k,v in row.items()}
def fmt(x,d=3):return '—' if x is None else f'{x:.{d}f}'
def read_trades(row):return assess.trades(row)
def dollar_metrics(row):
 trades=read_trades(row);p=[t['netUSD'] for t in trades];pos=sum(x for x in p if x>0);neg=-sum(x for x in p if x<0)
 return {'case_id':row['case_id'],'candidate_id':row['candidate_id'],'partition':row['partition'],'trade_count':len(p),'net_profit_USD':sum(p),'net_expectancy_USD':sum(p)/len(p) if p else None,'profit_factor_USD':pos/neg if neg else None,'profit_factor_R':row['profit_factor'],'net_expectancy_R':row['net_expectancy_R'],'note':'Fixed minimum lots but varying stop risk. Equal-weight R and dollar PnL need not have same sign.'}
